from itertools import combinations_with_replacement

def solve_m(m):
    # Check all multisets of residues of size m
    # Sum of x_i % m != 0
    # Check if any permutation sum(j * x_sigma(j)) % m == 0

    # To optimize, we only need to check multisets where not all x_i are equal
    # and sum(x_i) % m != 0.
    # If all x_i are equal, sum(x_i) = m * x_i = 0 mod m.

    for x in combinations_with_replacement(range(m), m):
        if sum(x) % m == 0:
            continue

        # Check if there's a permutation of x such that sum(j * x_sigma(j)) % m == 0
        # Coefficients are 1, 2, ..., m
        # Use DP to find all possible sums.
        # dp[mask] = set of possible sums using coefficients 1..k and residues in mask
        # where k = count_set_bits(mask)

        dp = [set() for _ in range(1 << m)]
        dp[0].add(0)
        for mask in range(1 << m):
            k = bin(mask).count('1')
            if k == m:
                continue
            coeff = k + 1
            for i in range(m):
                if not (mask & (1 << i)):
                    new_mask = mask | (1 << i)
                    for s in dp[mask]:
                        dp[new_mask].add((s + coeff * x[i]) % m)

        if 0 not in dp[(1 << m) - 1]:
            return False
    return True

