def get_S(m, c1):
    # sums of c1 elements from {1, ..., m}
    # Use DP: dp[i][j] is set of sums of i elements from {1, ..., j}
    dp = [set() for _ in range(c1 + 1)]
    dp[0].add(0)
    for i in range(1, m + 1):
        for j in range(min(i, c1), 0, -1):
            for s in dp[j-1]:
                dp[j].add(s + i)
    return dp[c1]

def solve_m_fast_final(m):
    # Check all multisets with at most 2 distinct values.
    # If such a multiset is a counterexample, then m is not a solution.
    # A multiset x with c1 copies of r and c2 copies of s is a counterexample if:
    # 1. (c1*r + c2*s) % m != 0
    # 2. For all J of size c1, (S_J * (r-s) + m(m+1)/2 * s) % m != 0

    S_all = m * (m + 1) // 2
    # Precompute all S(m, c1)
    all_S = {}
    for c1 in range(1, m):
        all_S[c1] = get_S(m, c1)

    for c1 in range(1, m):
        c2 = m - c1
        for r in range(m):
            for s in range(m):
                if (c1 * r + c2 * s) % m == 0:
                    continue

                d = (r - s) % m
                target = (-(S_all * s)) % m

                # Check if any s_j in all_S[c1] satisfies d * s_j = target mod m
                is_counterexample = True
                for s_j in all_S[c1]:
                    if (d * s_j) % m == target:
                        is_counterexample = False
                        break

                if is_counterexample:
                    return False # Found a counterexample
    return True

